    return sandbox.get_agent_body()

def agent_action(sandbox, agent_body, step_count):
    if "initial_state" not in MEM.data:
        MEM.data["initial_state"] = {
            "phase": "VERTICAL_ADJUST",
            "t": 0,
            "lx": None,
            "ly": None,
            "vx": 0.0,
            "vy": 0.0,
            "unlock_streak": 0,
            "exit_streak": 0,
        }

    state = MEM.data["initial_state"]
    pd = sandbox.get_agent_position()
    dt = TIME_STEP

    if state["lx"] is not None:
        state["vx"] = (pd[0] - state["lx"]) / dt
        state["vy"] = (pd[1] - state["ly"]) / dt
    state["lx"], state["ly"] = pd[0], pd[1]
    vxd, vyd = state["vx"], state["vy"]
    x, y = pd[0], pd[1]
    w_comp = _weight_comp(sandbox)
    front, up, down = sandbox.get_whisker_readings()

    # Whisker-based vertical correction
    if down < 0.3:
        ty = 2.0  # Too close to floor
    elif up < 0.3:
        ty = 1.0  # Too close to ceiling
    else:
        ty = TARGET_Y  # Ideal center

    # Control logic
    if state["phase"] == "VERTICAL_ADJUST":
        # Prioritize vertical alignment
        fy = 100.0 * (ty - y) - 30.0 * vyd + w_comp
        fx = 0.0  # No forward motion during vertical adjust
        if y >= 1.3:
            state["phase"] = "APPROACH"
    elif state["phase"] == "APPROACH":
        # Forward movement toward activation zone
        if x < 5.0:
            fx = 100.0
        else:
            fx = 20.0 * (7.0 - x) - 5.0 * vxd
        # Vertical PD control
        fy = 100.0 * (ty - y) - 30.0 * vyd + w_comp
        # Transition to unlock when in zone and slow
        if ACTIVATION_X_MIN <= x <= ACTIVATION_X_MAX and abs(vxd) < 0.5:
            state["phase"] = "UNLOCK"
            state["t"] = 0
    elif state["phase"] == "UNLOCK":
        vx_p, vy_p = sandbox.get_agent_velocity()
        spd = math.hypot(vx_p, vy_p)
        fx_cmd = BACKWARD_FX_THRESHOLD - 1.0  # -35.0 N
        fy_cmd = 100.0 * (ty - y) - 30.0 * vyd + w_comp
        if spd >= 0.99 * BACKWARD_SPEED_MAX:
            fx_cmd += -1.5 * vx_p
            fy_cmd -= 1.5 * vy_p
        fx, fy = fx_cmd, fy_cmd
        state["t"] += 1
        if state["t"] > 60:
            state["phase"] = "ESCAPE"
    elif state["phase"] == "ESCAPE":
        # Continue forward with moderate force
        fx = 15.0
        fy = 100.0 * (ty - y) - 30.0 * vyd + w_comp
        if x > _exit_x_min(sandbox):
            state["phase"] = "HOLD"
    elif state["phase"] == "HOLD":
        fx, fy = 0.0, w_comp

